/**
 * @name Code execution vulnerabilities
 * @description Using eval, exec, compile with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-execution
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CodeExecutionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for various code execution functions
    exists(DataFlow::CallCfgNode call |
      // Built-in code execution functions
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // __import__ function
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    )
  }
}

