 * @description Using getattr, setattr, or hasattr with untrusted input could lead to attribute manipulation
 * @kind path-problem
 * @problem.severity medium
 * @id py/attribute-manipulation
 * @tags security
 *        external/cwe/cwe-470
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module AttributeManipulationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for getattr, setattr, hasattr calls where attribute name could be user-controlled
    exists(API::CallNode call |
      call = API::builtin(["getattr", "setattr", "hasattr"]).getACall() and
      sink = call.getArg(1)  // Second argument is the attribute name
